-- loot, mobs and zones decode on first read. Each packed value is the table constructor the
-- entry had in plain form, so loadstring builds the same table, field order included.
do
    local D = CP.GatherData
    local packed = D.packed
    local loadstring, pairs, rawget, rawset = loadstring, pairs, rawget, rawset

    -- Entries decoded so far, per part.
    local count = { loot = 0, mobs = 0, zones = 0 }
    D.unpacked = count

    local function decode(s)
        return loadstring("return " .. s, "=GatherData")()
    end

    -- pairs() on loot or mobs sees only decoded entries. This entry makes such a loop fail
    -- on its first use of the value.
    local PAIRS = "pairs() sees only decoded entries; use CP.GatherData.Each"
    local function wrong() error(PAIRS, 2) end

    local function lazy(part)
        local src = packed[part]
        return setmetatable({ [PAIRS] = wrong }, { __index = function(t, key)
            local s = src[key]
            if s == nil then return nil end
            local v = decode(s)
            src[key] = nil
            rawset(t, key, v)
            count[part] = count[part] + 1
            return v
        end })
    end
    D.loot, D.mobs = lazy("loot"), lazy("mobs")

    -- A zone's map, size, levels, instance and fishing are plain. Reading one of these
    -- fields decodes the rest.
    local HEAVY = { mobs = true, nodes = true, mix = true, water = true, cloth = true }
    local zoneSrc, zoneOf = packed.zones, {}
    local zoneMeta = { __index = function(z, key)
        if not HEAVY[key] then return nil end
        local zone = zoneOf[z]
        local s = zone and zoneSrc[zone]
        if s == nil then return nil end
        zoneSrc[zone] = nil
        for k, v in pairs(decode(s)) do rawset(z, k, v) end
        count.zones = count.zones + 1
        return rawget(z, key)
    end }
    for zone, z in pairs(D.zones) do
        zoneOf[z] = zone
        setmetatable(z, zoneMeta)
    end

    -- Every key and value of `part` ("loot", "mobs" or "zones"), decoding each. For tests and
    -- tools: a whole-table loop in play uses an index instead.
    function D.Each(part)
        local t = D[part]
        local keys = {}
        for key in pairs(part ~= "zones" and packed[part] or {}) do keys[#keys + 1] = key end
        for key in pairs(t) do
            if key ~= PAIRS then keys[#keys + 1] = key end
        end
        local i = 0
        return function()
            i = i + 1
            local key = keys[i]
            if key ~= nil then return key, t[key] end
        end
    end

    -- A generated index, decoded on each call; callers keep what they build from it.
    function D.Index(name)
        local s = D.index[name]
        return s and decode(s) or nil
    end
end
